BLOB = r'''{"requirements.txt": "cmVxdWVzdHM9PTIuMzIuMwpiZWF1dGlmdWxzb3VwND09NC4xMi4zCmx4bWw9PTUuMy4wCnBhbmRhcz09Mi4yLjMKbnVtcHk9PTIuMS4zCm9wZW5weXhsPT0zLjEuNQp4bHJkPT0yLjAuMQpwZGZwbHVtYmVyPT0wLjExLjQKcHl0aG9uLWRhdGV1dGlsPT0yLjkuMC5wb3N0MAo=", ".gitignore": "LmNhY2hlLwpfX3B5Y2FjaGVfXy8KKi5weWMK", "index.html": "", "README.md": "", ".github/workflows/update-dashboard.yml": "", "scripts/registry.json": "", "scripts/common.py": "", "scripts/update_data.py": "", "scripts/build_html.py": "", "scripts/sources/__init__.py": "", "scripts/sources/te_investing.py": "", "scripts/sources/cbonds.py": "", "scripts/sources/cbr.py": "", "scripts/sources/rosstat.py": "", "scripts/sources/misc.py": "", "data/dashboard.json": "", "data/budget.json": "", "data/manual_overrides.csv": "Y29kZSxwZXJpb2QsdmFsdWUK", "templates/dashboard.html": ""}'''

"""Разворачивает репозиторий макродашборда РФ в текущую папку.

Запуск:  python setup_dashboard.py
Затем:   git init && git add . && git commit -m "init" && git push
"""
import base64, json, os, sys

FILES = json.loads(BLOB)

def main():
    target = sys.argv[1] if len(sys.argv) > 1 else "rf-macro-dashboard"
    for path, b64 in FILES.items():
        full = os.path.join(target, path)
        os.makedirs(os.path.dirname(full), exist_ok=True)
        with open(full, "wb") as f:
            f.write(base64.b64decode(b64))
        print("создан", full)
    print(f"\nГотово: {len(FILES)} файлов в {os.path.abspath(target)}")
    print("Дальше: cd", target, "&& git init && git add . && git commit -m init && git push")

if __name__ == "__main__":
    main()
